def has_short_cycle(G, max_len=6):
    # Check for cycles up to max_len
    # Use BFS from each node limited depth
    for s in G:
        # BFS tree
        parent = {s: None}
        level = {s: 0}
        queue = [s]
        for u in queue:
            if level[u] >= max_len // 2 + 1:
                continue
            for v in G[u]:
                if v not in parent:
                    parent[v] = u
                    level[v] = level[u] + 1
                    queue.append(v)
                elif v != parent[u] and level[u] + level[v] < max_len:
                    # Found a cycle
                    return True
    return False

def random_regular_graph_girth(n, d, max_tries=1000):
    for _ in range(max_tries):
        try:
            G = nx.random_regular_graph(d, n, seed=random.randint(0, 1000000))
            if not has_short_cycle(G, 6):
                return G
        except:
            pass
    return None

