def find_shortest_cycle(G):
    n = len(G)
    shortest = None
    for s in range(n):
        # BFS
        parent = {s: -1}
        dist = {s: 0}
        queue = [s]
        for u in queue:
            for v in G[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if shortest is None or cycle_len < shortest:
