# Check 5-colorability using a proper algorithm
# Since it's 3-regular, Brooks' theorem says it's 3-colorable unless it's K4
# Let's verify with a simple backtracking
def is_colorable(G, k):
    n = len(G)
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in G[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0), colors

